<?php
require_once dirname(__DIR__).'/framework.php';require_once __DIR__.'/sys.conf.php';
Identity::requireIdentity('backend',true);
$kernel=SMF\Core\Kernel::boot();$registry=$kernel->modules();$notice='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    try {
        $action=$_POST['action']??'';
        if(in_array($action,['enable','disable'],true)){$registry->$action((string)($_POST['module']??''));$kernel->audit()->record('module.'.$action,(string)$_POST['module']);$notice='Modulstatus gespeichert.';}
        elseif($action==='branding'){
            $input=array_intersect_key($_POST,array_flip(['site_name','site_url','support_email','logo_url','accent','environment']));
            $input['direct_links']=json_decode($_POST['direct_links']??'[]',true,32,JSON_THROW_ON_ERROR);
            SMF\Core\ShopSettings::save($input);$kernel->audit()->record('settings.shop');$notice='Betreibereinstellungen gespeichert.';
        }else throw new RuntimeException('Aktion nicht unterstützt.');
    }catch(Throwable $e){http_response_code(422);$notice='Änderung nicht möglich. Installation, Abhängigkeiten und Eingaben prüfen.';}
}
function module_escape($value){return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$settings=SMF\Core\ShopSettings::all();$heartbeatFile=HttpSecurity::privateDirectory('jobs').'/heartbeat.json';$heartbeat=is_file($heartbeatFile)&&!is_link($heartbeatFile)?json_decode(file_get_contents($heartbeatFile),true):null;header("Content-Security-Policy: default-src 'self'; style-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'self'");
?><!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Module und Shop</title><link rel="stylesheet" href="assets/modules.css"><body><main><a href="index.php">Zur Framework-Verwaltung</a><h1>Module und Shop</h1><p role="status"><?=module_escape($notice)?></p><p>Installation und Datenmigration erfolgen über die CLI. Gebuchte Daten bleiben beim Deaktivieren erhalten.</p><table><thead><tr><th>Modul</th><th>Version</th><th>Status</th><th>Aktion</th></tr></thead><tbody>
<?php foreach($registry->catalog()as$id=>$manifest):?><tr><td><?=module_escape($manifest['name']??$id)?><small><?=module_escape($id)?></small></td><td><?=module_escape($manifest['version'])?></td><td><?=$registry->installed($id)?($registry->enabled($id)?'Aktiv':'Deaktiviert'):'Nicht installiert'?></td><td><?php if($registry->installed($id)):?><form method="post"><?=HttpSecurity::csrfField()?><input type="hidden" name="module" value="<?=module_escape($id)?>"><button name="action" value="<?=$registry->enabled($id)?'disable':'enable'?>"><?=$registry->enabled($id)?'Deaktivieren':'Aktivieren'?></button></form><?php endif?></td></tr><?php endforeach?></tbody></table>
<h2>Betreiber und Oberfläche</h2><form method="post"><?=HttpSecurity::csrfField()?><input type="hidden" name="action" value="branding"><?php foreach(['site_name'=>'Name','site_url'=>'Shop-URL (HTTPS)','support_email'=>'Support-E-Mail','logo_url'=>'Logo-URL (optional, HTTPS)','accent'=>'Akzentfarbe']as$key=>$label):?><label><?=module_escape($label)?><input name="<?=$key?>" value="<?=module_escape($settings[$key])?>"></label><?php endforeach?><label>Umgebung<select name="environment"><?php foreach(['sandbox'=>'Testbetrieb','live'=>'Livebetrieb']as$value=>$label):?><option value="<?=$value?>" <?=$settings['environment']===$value?'selected':''?>><?=$label?></option><?php endforeach?></select></label><p>Live-Schreibzugriffe benötigen zusätzlich die Freigabe in der privaten Betreiberkonfiguration.</p><label>Direktzugänge als JSON<textarea name="direct_links" rows="5"><?=module_escape(json_encode($settings['direct_links'],JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT))?></textarea></label><button>Speichern</button></form><h2>Betrieb</h2><p>Letzte Worker-Ausführung: <?=isset($heartbeat['at'])?module_escape(gmdate('Y-m-d H:i:s \U\T\C',(int)$heartbeat['at'])):'Noch keine'?></p><p>Worker: <code>php bin/worker.php --limit=10 --retain-days=90</code></p><p>Öffentlicher Zustand: <a href="/public/status.php">Status</a> · <a href="/">Shop öffnen</a></p></main></body></html>
